453	     *  stores them; null: none); refused when another person on the sheet holds the contact. */
454	    @Transactional
455	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact,
456	            String tags) {
457	        sheets.load(sheetId, user);
458	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, name) || people.existsAlias(sheetId, name)
459	                || inTree(treeNames(sheetId), name)) {
460	            throw nameInUse();
461	        }
462	        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
463	            throw contactInUse();
464	        }
465	        grades.checkChoosable(sheetId, grade);
466	        return rollup.tracking(sheetId, user, () -> {
467	            Person fresh = new Person(sheetId, name, grade, people.nextPosition(sheetId));
468	            fresh.setTerms(terms);
469	            fresh.setContact(contact);
470	            fresh.setTags(tags);
471	            Person person = saveUnique(fresh);
472	            claims.keepTags(sheetId, tags);
473	            audit.recordOnCommit(record("PERSON_ADDED", sheetId, user, person, sheets.today(sheetId))
474	                    + (terms != null ? " terms=" + terms : "")
475	                    + (contact != null ? " contact=" + contact : ""));
476	            return person;
477	        });
478	    }
