487	            LocalDate gradeFrom, Integer terms, String contact) {
488	        Person person = people.findByIdAndSheetId(personId, sheetId)
489	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
490	        return edit(sheetId, user, personId, version, name, grade, gradeFrom, terms, contact, person.getTags());
