501	    /** Edit a person as above, recording their terms from a day (null: from the beginning of time),
502	     *  keeping those recorded for other days. */
503	    @Transactional
504	    public Person edit(String sheetId, String user, long personId, long version, String name, String grade,
505	            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, String tags) {
506	        Person person = people.findByIdAndSheetId(personId, sheetId)
507	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
508	        if (person.getVersion() != version) {
509	            throw changedMeanwhile();
510	        }
511	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, name, personId)
512	                || people.existsAlias(sheetId, name)) {
513	            throw nameInUse();
514	        }
515	        Set<String> tree = treeNames(sheetId);
516	        if (inTree(tree, name) || person.getAliases().stream().anyMatch(a -> inTree(tree, a))) {
517	            throw nameInUse();
518	        }
519	        if (contact != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contact, personId)) {
520	            throw contactInUse();
521	        }
522	        return save(sheetId, user, person, name, grade, gradeFrom, terms, termsFrom, contact, tags);
523	    }
