525	    /** Give each of the people a grade from a day (null: the sheet's today), in list order, exactly as the person form would: each keeps their name, terms and contact and
526	     *  is followed by their own PERSON_EDITED and rollup lines. Refused as a whole, changing no one,
527	     *  when an id names no person on the sheet. A viewer has each of them refused: no one changes. */
528	    @Transactional
529	    public List<Person> grade(String sheetId, String user, Set<Long> personIds, String grade, LocalDate gradeFrom) {
530	        if (SheetRole.VIEWER.equals(roles.roleOf(sheetId, user))) {
531	            return List.of();
532	        }
533	        List<Person> chosen = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
534	                .filter(p -> personIds.contains(p.getId())).toList();
535	        if (chosen.size() != personIds.size()) {
536	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet");
537	        }
538	        return chosen.stream()
539	                .map(p -> save(sheetId, user, p, p.getName(), grade, gradeFrom, p.getTerms(), null, p.getContact(),
540	                        p.getTags()))
541	                .toList();
542	    }
543	
544	    /** Save the person's name, grade from a day, terms from a day, contact and tags as an edit does,
545	     *  recording it; the terms recorded, when they change, as those in force on the sheet's today. */
546	    private Person save(String sheetId, String user, Person person, String name, String grade, LocalDate gradeFrom,
547	            Integer terms, LocalDate termsFrom, String contact, String tags) {
548	        if (choosesGrade(sheetId, person, grade, gradeFrom)) {
549	            grades.checkChoosable(sheetId, grade);
550	        }
551	        return rollup.tracking(sheetId, user, () -> {
552	            LocalDate today = sheets.today(sheetId);
553	            Integer undatedBefore = person.getTerms();
554	            List<TermsFrom> datedBefore = person.getDatedTerms();
555	            String contactBefore = person.getContact();
556	            person.setName(name);
557	            person.setTermsFrom(terms, termsFrom);
558	            boolean termsChanged = !Objects.equals(undatedBefore, person.getTerms())
559	                    || !sameTerms(datedBefore, person.getDatedTerms());
560	            Integer termsNow = person.termsOn(today);
561	            person.setContact(contact);
562	            person.setTags(tags);
563	            claims.keepTags(sheetId, tags);
564	            if (choosesGrade(sheetId, person, grade, gradeFrom)) {
565	                person.setGradeFrom(grade, gradeFrom != null ? gradeFrom : today);
566	            }
567	            Person saved = saveUnique(person);
568	            audit.recordOnCommit(record("PERSON_EDITED", sheetId, user, saved, today)
569	                    + (termsChanged ? " terms=" + (termsNow != null ? termsNow : "") : "")
570	                    + (Objects.equals(contactBefore, contact) ? "" : " contact=" + (contact != null ? contact : "")));
571	            return saved;
572	        });
573	    }
