575	    /** Whether saving the grade from a day (null: the sheet's today) records it for the person, so
576	     *  is a choice of it: a grade left as the one in force on the sheet's today, with no day given,
577	     *  is not. */
578	    private boolean choosesGrade(String sheetId, Person person, String grade, LocalDate gradeFrom) {
579	        return gradeFrom != null || !grade.equals(person.gradeOn(sheets.today(sheetId)));
580	    }
