582	    private static boolean sameTerms(List<TermsFrom> a, List<TermsFrom> b) {
583	        if (a.size() != b.size()) {
584	            return false;
585	        }
586	        for (int i = 0; i < a.size(); i++) {
587	            if (!a.get(i).getFromDate().equals(b.get(i).getFromDate())
588	                    || !Objects.equals(a.get(i).getTerms(), b.get(i).getTerms())) {
589	                return false;
590	            }
591	        }
592	        return true;
593	    }
