612	    /** Whether the person clashes: their name or an alias is used as a name or alias on another
613	     *  sheet of their sheet's tree (see {@link SheetService#tree}). */
614	    @Transactional(readOnly = true)
615	    public boolean clashing(String sheetId, Person person) {
