619	    /** A test of whether a person on the sheet clashes, reading the sheet's tree once. */
620	    @Transactional(readOnly = true)
621	    public Predicate<Person> clashing(String sheetId) {
622	        Set<String> tree = treeNames(sheetId);
623	        if (tree.isEmpty()) {
624	            return p -> false;
625	        }
626	        return p -> inTree(tree, p.getName()) || p.getAliases().stream().anyMatch(a -> inTree(tree, a));
627	    }
628	
629	    /** The names and aliases used on the other sheets of the sheet's tree, lower-cased. */
630	    private Set<String> treeNames(String sheetId) {
631	        Set<String> tree = sheets.tree(sheetId);
632	        if (tree.isEmpty()) {
633	            return Set.of();
634	        }
635	        Set<String> names = new HashSet<>(people.namesOn(tree));
636	        names.addAll(people.aliasesOn(tree));
637	        return names;
638	    }
