644	    /** Swap a person with the one above them in the list (up) or below them (down), recording their
645	     *  new position counting from 1; refused when they are at the top and moving up, or at the
646	     *  bottom and moving down. Answers the people in their new list order. */
647	    @Transactional
648	    public List<Person> move(String sheetId, String user, long personId, boolean up) {
649	        List<Person> listed = new ArrayList<>(people.findBySheetIdOrderByPositionAscIdAsc(sheetId));
650	        int at = -1;
651	        for (int i = 0; i < listed.size(); i++) {
652	            if (listed.get(i).getId() == personId) {
653	                at = i;
654	            }
655	        }
656	        if (at < 0) {
657	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet");
658	        }
659	        int to = up ? at - 1 : at + 1;
660	        if (to < 0 || to >= listed.size()) {
661	            throw new ResponseStatusException(HttpStatus.CONFLICT,
662	                    up ? "The person at the top cannot move up" : "The person at the bottom cannot move down");
663	        }
664	        Person moved = listed.get(at);
665	        Collections.swap(listed, at, to);
666	        // Number the whole list afresh from 1, so people who shared a position are told apart.
667	        for (int i = 0; i < listed.size(); i++) {
668	            if (listed.get(i).getPosition() != i + 1) {
669	                people.placeAt(listed.get(i).getId(), i + 1);
670	            }
671	        }
672	        audit.recordOnCommit("PERSON_MOVED sheet=" + sheetId + " by=" + user + " name=" + moved.getName()
673	                + " position=" + (to + 1));
674	        return people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
675	    }
