752	    /** Flag a person with a reason (kept trimmed) until a day (included; null: the sheet's
753	     *  today), replacing any flag they had. Refused unless the user is a steward (403) and the reason is not blank (400). */
754	    @Transactional
755	    public Person flag(String sheetId, String user, long personId, String reason, LocalDate until) {
756	        Person person = people.findByIdAndSheetId(personId, sheetId)
757	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
758	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
759	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can flag a person");
760	        }
761	        if (reason == null || reason.isBlank()) {
762	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Give a reason for the flag");
763	        }
764	        String why = reason.trim();
765	        LocalDate last = until != null ? until : sheets.today(sheetId);
766	        person.flag(why, last);
767	        Person saved = saveUnique(person);
768	        audit.recordOnCommit("PERSON_FLAGGED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
769	                + " reason=" + why + " until=" + last);
