774	     *  their pending claims as a steward may. */
775	    @Transactional
776	    public Person setApprover(String sheetId, String user, long personId, String approver) {
777	        Person person = people.findByIdAndSheetId(personId, sheetId)
778	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
779	        String who = approver == null || approver.isBlank() ? null : approver.trim();
780	        person.setApprover(who);
781	        Person saved = saveUnique(person);
782	        audit.recordOnCommit("APPROVER_SET sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
783	                + " user=" + (who == null ? "" : who));
784	        return saved;
785	    }
786	
787	    /** A record of the person with the grade in force on the sheet's today. */
788	    private static String record(String event, String sheetId, String user, Person person, LocalDate today) {
789	        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade="
790	                + person.gradeOn(today);
791	    }
792	
793	    /** Save, refusing a name or contact another user took on the sheet in the meantime, or a person
794	     *  another user saved in the meantime. */
795	    private Person saveUnique(Person person) {
796	        try {
797	            return people.saveAndFlush(person);
798	        } catch (DataIntegrityViolationException e) {
799	            String constraint = String.valueOf(e.getMostSpecificCause().getMessage()).toUpperCase(Locale.ROOT);
800	            throw constraint.contains("PERSON_SHEET_CONTACT_UNIQUE") ? contactInUse() : nameInUse();
801	        } catch (OptimisticLockingFailureException e) {
802	            throw changedMeanwhile();
803	        }
804	    }
805	
806	    private static ResponseStatusException changedMeanwhile() {
807	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
808	                "Someone else saved this person in the meantime");
809	    }
810	
811	    private static ResponseStatusException contactInUse() {
812	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already held on this sheet");
813	    }
814	
815	    private static ResponseStatusException nameInUse() {
816	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet");
817	    }
818	}
